 *
 * @param {Function} fn - The function to debounce.
 * @param {number} wait - The number of milliseconds to delay execution.
 * @returns {Function} A new debounced function that, when invoked, resets
 *   the timer and delays the call to `fn`.
 *
 * @example
 * // Usage example:
 * const log = debounce((msg) => console.log(msg), 300);
 * log('Hello'); // Will log 'Hello' after 300ms, unless called again within that time.
 */
function debounce(fn, wait) {
  let timeoutId = null;

  const debounced = function (...args) {
    const context = this;

    // Clear any existing timer to reset the delay
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
    }

    // Set a new timer to invoke `fn` after `wait` ms
    timeoutId = setTimeout(() => {
      fn.apply(context, args);
      timeoutId = null; // Optional: reset for garbage collection
    }, wait);
  };

  /**
   * Optional: add a `cancel` method to allow manual cancellation of the pending call.
   * @returns {void}
   */
  debounced.cancel = function () {
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
      timeoutId = null;
    }
  };

  return debounced;
}
